"use client";
import * as React from "react";
import { Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
export function PopButton({
  loading = false,
  size = "default",
  disabled,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { loading?: boolean }) {
  return (
    <Button
      {...props}
      size={size}
      className={cn(
        "rounded-full focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-transparent",
        props.className,
      )}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
    >
      {loading ? (
        <Loader2 data-icon="inline-start" className="animate-spin" />
      ) : null}
      {children}
    </Button>
  );
}

"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
} from "@/components/ui/field";
export function PopInput({
  label,
  hint,
  error,
  id,
  ...props
}: React.ComponentProps<typeof Input> & {
  label: string;
  hint?: string;
  error?: string;
}) {
  const autoId = React.useId();
  const fieldId = id || autoId;
  const descriptionId = `${fieldId}-description`;
  return (
    <Field data-invalid={!!error} className="gap-1.5">
      <FieldLabel htmlFor={fieldId}>{label}</FieldLabel>
      <Input
        {...props}
        className={cn(
          "rounded-[var(--radius-element,12px)] focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-input",
          props.className,
        )}
        id={fieldId}
        aria-invalid={!!error}
        aria-describedby={error || hint ? descriptionId : undefined}
      />
      {error ? (
        <FieldError id={descriptionId} className="text-xs">
          {error}
        </FieldError>
      ) : hint ? (
        <FieldDescription id={descriptionId} className="text-xs">
          {hint}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

import type { ReactNode } from "react";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/components/ui/card";
export function PopCard({
  title,
  description,
  children,
  footer,
}: {
  title: string;
  description?: string;
  children: ReactNode;
  footer?: ReactNode;
}) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        {description ? <CardDescription>{description}</CardDescription> : null}
      </CardHeader>
      <CardContent>{children}</CardContent>
      {footer ? <CardFooter>{footer}</CardFooter> : null}
    </Card>
  );
}

import type { ReactNode } from "react";
import { Badge } from "@/components/ui/badge";
export function PopBadge({
  status = "neutral",
  children,
}: {
  status?: "neutral" | "success" | "warning";
  children: ReactNode;
}) {
  return (
    <Badge
      variant={
        status === "success"
          ? "default"
          : status === "warning"
            ? "outline"
            : "secondary"
      }
      className="rounded-full"
    >
      <span aria-hidden="true" className="size-1 rounded-full bg-current" />
      {children}
    </Badge>
  );
}

"use client";
import * as React from "react";
import { Switch } from "@/components/ui/switch";
export function PopSwitch({
  label,
  description,
  id,
  ...props
}: React.ComponentProps<typeof Switch> & {
  label: string;
  description?: string;
}) {
  const autoId = React.useId();
  const fieldId = id || autoId;
  return (
    <div className="flex items-center justify-between gap-6">
      <label
        htmlFor={fieldId}
        className="flex flex-col gap-1 text-sm font-medium cursor-pointer"
      >
        {label}
        {description ? (
          <span className="text-xs font-normal text-muted-foreground">
            {description}
          </span>
        ) : null}
      </label>
      <Switch
        className="focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-transparent"
        size="default"
        {...props}
        id={fieldId}
      />
    </div>
  );
}

"use client";
import * as React from "react";
import { Checkbox } from "@/components/ui/checkbox";
export function PopCheckbox({
  label,
  description,
  id,
  ...props
}: React.ComponentProps<typeof Checkbox> & {
  label: string;
  description?: string;
}) {
  const autoId = React.useId();
  const fieldId = id || autoId;
  return (
    <div className="flex items-start gap-3">
      <Checkbox
        className="focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-input data-checked:focus-visible:border-primary"
        {...props}
        id={fieldId}
      />
      <label
        htmlFor={fieldId}
        className="flex flex-col gap-1 text-sm font-medium cursor-pointer"
      >
        {label}
        {description ? (
          <span className="text-xs font-normal text-muted-foreground">
            {description}
          </span>
        ) : null}
      </label>
    </div>
  );
}

"use client";
import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
export function PopTabs({
  items,
  defaultValue,
}: {
  items: { value: string; label: string; content: ReactNode }[];
  defaultValue?: string;
}) {
  return (
    <Tabs defaultValue={defaultValue || items[0]?.value}>
      <TabsList className="rounded-full">
        {items.map((item) => (
          <TabsTrigger
            key={item.value}
            value={item.value}
            className="rounded-full focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-transparent"
          >
            {item.label}
          </TabsTrigger>
        ))}
      </TabsList>
      {items.map((item) => (
        <TabsContent
          key={item.value}
          value={item.value}
          className="rounded-full"
        >
          {item.content}
        </TabsContent>
      ))}
    </Tabs>
  );
}

"use client";
import type { ReactNode } from "react";
import {
  Accordion,
  AccordionItem,
  AccordionTrigger,
  AccordionContent,
} from "@/components/ui/accordion";
export function PopAccordion({
  items,
}: {
  items: { question: string; answer: ReactNode }[];
}) {
  return (
    <Accordion type="single" collapsible>
      {items.map((item, index) => (
        <AccordionItem key={index} value={String(index)}>
          <AccordionTrigger className="py-3 text-sm focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-transparent focus-visible:after:border-transparent">
            {item.question}
          </AccordionTrigger>
          <AccordionContent className="text-sm">{item.answer}</AccordionContent>
        </AccordionItem>
      ))}
    </Accordion>
  );
}

"use client";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
export function PopDialog({
  trigger,
  title,
  description,
  children,
}: {
  trigger: string;
  title: string;
  description?: string;
  children: ReactNode;
}) {
  return (
    <Dialog>
      <DialogTrigger asChild>
        <Button
          className="focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-transparent"
          variant="outline"
        >
          {trigger}
        </Button>
      </DialogTrigger>
      <DialogContent className="focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 [&_button:focus-visible]:outline-none [&_button:focus-visible]:ring-0">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description ? (
            <DialogDescription>{description}</DialogDescription>
          ) : null}
        </DialogHeader>
        {children}
      </DialogContent>
    </Dialog>
  );
}

"use client";
import { useId } from "react";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectGroup,
  SelectItem,
} from "@/components/ui/select";
export function PopSelect({
  label,
  placeholder = "请选择",
  items,
  value,
  onValueChange,
}: {
  label: string;
  placeholder?: string;
  items: { value: string; label: string }[];
  value?: string;
  onValueChange?: (value: string) => void;
}) {
  const id = useId();
  return (
    <div className="flex flex-col gap-2">
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <Select value={value} onValueChange={onValueChange}>
        <SelectTrigger
          size="default"
          id={id}
          className="w-full rounded-[var(--radius-element,12px)] focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-input"
        >
          <SelectValue placeholder={placeholder} />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {items.map((item) => (
              <SelectItem key={item.value} value={item.value}>
                {item.label}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
    </div>
  );
}

import { Progress } from "@/components/ui/progress";
export function PopProgress({
  label,
  value,
  description,
}: {
  label: string;
  value: number;
  description?: string;
}) {
  const percent = Math.min(
    100,
    Math.max(0, Number.isFinite(value) ? value : 0),
  );
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between gap-4 text-sm">
        <span className="font-medium">{label}</span>
        <span className="tabular-nums text-muted-foreground">
          {Math.round(percent)}%
        </span>
      </div>
      <Progress
        value={percent}
        aria-label={label}
        aria-valuenow={percent}
        aria-valuemin={0}
        aria-valuemax={100}
      />
      {description ? (
        <p className="text-xs text-muted-foreground">{description}</p>
      ) : null}
    </div>
  );
}

import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
export function PopAvatarStack({
  people,
  max = 4,
}: {
  people: { name: string; image?: string }[];
  max?: number;
}) {
  const limit = Math.max(1, Math.floor(max));
  return (
    <div
      className="flex"
      aria-label={people.map((person) => person.name).join(", ")}
    >
      {people.slice(0, limit).map((person, index) => (
        <Avatar
          key={`${person.name}-${index}`}
          size="default"
          className="ring-2 ring-background -ml-1.5 first:ml-0"
        >
          {person.image ? (
            <AvatarImage src={person.image} alt={person.name} />
          ) : null}
          <AvatarFallback>
            {person.name
              .split(" ")
              .map((part) => part[0])
              .slice(0, 2)
              .join("")}
          </AvatarFallback>
        </Avatar>
      ))}
      {people.length > limit ? (
        <Avatar
          size="default"
          className="ring-2 ring-background -ml-1.5 first:ml-0"
        >
          <AvatarFallback>+{people.length - limit}</AvatarFallback>
        </Avatar>
      ) : null}
    </div>
  );
}
